Here is a production-ready, idiomatic Terraform implementation that satisfies all acceptance criteria and the canonical scenario specification.

### 📁 Directory Structure
```
terraform/
├── main.tf
├── providers.tf
├── variables.tf
├── outputs.tf
├── dev.tfvars
├── prod.tfvars
└── modules/
    └── app_infrastructure/
        ├── main.tf
        ├── variables.tf
        └── outputs.tf
```

---

### 🧱 Module: `modules/app_infrastructure/`

#### `modules/app_infrastructure/main.tf`
```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# 1. S3 Bucket (Application Assets)
resource "aws_s3_bucket" "app_assets" {
  bucket = var.s3_bucket_name
  tags   = var.tags
}

resource "aws_s3_bucket_versioning" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = var.s3_encryption_algorithm
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Cross-region replication (Prod only)
resource "aws_s3_bucket_replication_configuration" "app_assets" {
  count  = var.enable_replication ? 1 : 0
  bucket = aws_s3_bucket.app_assets.id
  role   = var.replication_role_arn

  rule {
    id     = "cross-region-replication"
    status = "Enabled"
    destination {
      bucket        = var.replication_destination_bucket_arn
      storage_class = "STANDARD"
    }
    filter {}
  }
}

# 2. RDS PostgreSQL Instance
resource "aws_db_subnet_group" "app" {
  name       = "${var.name}-db-subnet-group"
  subnet_ids = var.vpc_subnet_ids
  tags       = var.tags
}

resource "aws_db_instance" "app" {
  identifier              = var.rds_identifier
  engine                  = "postgres"
  engine_version          = var.rds_engine_version
  instance_class          = var.rds_instance_class
  allocated_storage       = var.rds_allocated_storage
  db_name                 = var.rds_db_name
  username                = var.rds_username
  password                = var.rds_password
  port                    = 5432
  db_subnet_group_name    = aws_db_subnet_group.app.name
  skip_final_snapshot     = true
  deletion_protection     = true
  publicly_accessible     = false
  storage_encrypted       = var.rds_storage_encrypted
  multi_az                = var.rds_multi_az
  backup_retention_period = var.rds_backup_retention_period
  backup_window           = "03:00-04:00"
  maintenance_window      = "Sun:04:00-Sun:05:00"
  vpc_security_group_ids  = var.vpc_security_group_ids
  tags                    = var.tags
}

# 3. IAM Role (Service Account)
resource "aws_iam_role" "app_service" {
  name               = "${var.name}-app-service-role"
  assume_role_policy = var.assume_role_policy
  tags               = var.tags
}

resource "aws_iam_role_policy" "app_service" {
  name = "${var.name}-app-service-policy"
  role = aws_iam_role.app_service.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AppServicePermissions"
        Effect = "Allow"
        Action = var.iam_allowed_actions
        Resource = var.iam_allowed_resources
      }
    ]
  })
}
```

#### `modules/app_infrastructure/variables.tf`
```hcl
variable "name" {
  description = "Environment or project name prefix"
  type        = string
}

variable "tags" {
  description = "Common tags for all resources"
  type        = map(string)
  default     = {}
}

# S3 Variables
variable "s3_bucket_name" {
  description = "Name of the application assets S3 bucket"
  type        = string
}

variable "s3_encryption_algorithm" {
  description = "SSE algorithm: AES256 or aws:kms"
  type        = string
  default     = "AES256"
}

variable "enable_replication" {
  description = "Enable cross-region replication (prod only)"
  type        = bool
  default     = false
}

variable "replication_role_arn" {
  description = "IAM role ARN with replication permissions"
  type        = string
  default     = ""
}

variable "replication_destination_bucket_arn" {
  description = "ARN of the destination bucket for replication"
  type        = string
  default     = ""
}

